  --card-bg:      #ffffff;
  --card-shadow:  0 4px 24px rgba(0, 0, 0, 0.13);
  --text-primary: #1a1a2e;
  --text-muted:   #666;
  --border:       #e5e5e5;
  --input-bg:     #f5f5f5;
  --btn-primary:  #6E57E5;
  --btn-primary-h:#5643c7;
  --btn-secondary:#9b59b6;
  --btn-ghost-bg: transparent;
  --btn-ghost-border: #ccc;
  --clock-color:  #6E57E5;
  --greeting-color:#333;
  --timer-color:  #6E57E5;
  --delete-bg:    #e74c3c;
  --delete-h:     #c0392b;
  --pill-bg:      #3498db;
  --pill-h:       #2980b9;
  --pill-text:    #fff;
  --duplicate-color: #e74c3c;
  --modal-overlay: rgba(60, 40, 140, 0.65);
  --transition:   0.25s ease;
}

/* Dark mode overrides */
body.dark {
  --bg:           #12101f;
  --bg-gradient:  linear-gradient(135deg, #12101f 0%, #1e1a3a 100%);
  --card-bg:      #1e1a3a;
  --card-shadow:  0 4px 28px rgba(0, 0, 0, 0.45);
  --text-primary: #e8e0ff;
  --text-muted:   #a09cbd;
  --border:       #2e2a4a;
  --input-bg:     #2a2545;
  --btn-primary:  #7c6af0;
  --btn-primary-h:#6E57E5;
  --btn-secondary:#7d3caf;
  --btn-ghost-border: #4a4070;
  --clock-color:  #c3b1ff;
  --greeting-color:#ddd5ff;
  --timer-color:  #c3b1ff;
  --pill-bg:      #1a6fa8;
  --pill-h:       #1558884;
  --modal-overlay: rgba(10, 8, 30, 0.80);
}

/* ── Body & background ── */
body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--bg-gradient);
  min-height: 100vh;
  color: var(--text-primary);
  transition: background var(--transition), color var(--transition);
}

/* ══════════════════════════════════
   MODAL
══════════════════════════════════ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: var(--modal-overlay);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  backdrop-filter: blur(4px);
  transition: opacity var(--transition);
}

.modal-overlay.hidden {
  display: none;
}

.modal-box {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 2.5rem 2rem;
  width: min(90vw, 400px);
  text-align: center;
  box-shadow: 0 8px 40px rgba(0,0,0,0.3);
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-box h2 {
  font-size: 1.6rem;
  color: var(--text-primary);
}

.modal-box p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.modal-input {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 2px solid var(--border);
  border-radius: 10px;
  font-size: 1rem;
  background: var(--input-bg);
  color: var(--text-primary);
  outline: none;
  transition: border-color var(--transition);
}

.modal-input:focus {
  border-color: var(--btn-primary);
}

/* ══════════════════════════════════
   DASHBOARD GRID
══════════════════════════════════ */
.dashboard {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.25rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Middle row: 2 equal columns ── */
.middle-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}

/* ══════════════════════════════════
   CARDS
══════════════════════════════════ */
.card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 1.75rem 2rem;
  box-shadow: var(--card-shadow);
  transition: background var(--transition), box-shadow var(--transition);
  position: relative;
}

.card-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 1.25rem;
  letter-spacing: 0.01em;
}

/* ── Top Card ── */
.card-top {
  text-align: center;
  padding: 2.25rem 2rem;
}

.clock {
  font-size: clamp(2.8rem, 8vw, 4.5rem);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
  color: var(--clock-color);
  line-height: 1;
  transition: color var(--transition);
}

.date-display {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 0.4rem;
  font-weight: 500;
}

.greeting {
  font-size: clamp(1.2rem, 3vw, 1.6rem);
  font-weight: 700;
  color: var(--greeting-color);
  margin-top: 0.6rem;
  transition: color var(--transition);
}

/* Dark mode toggle button — top-right of card */
.dark-toggle {
  position: absolute;
  top: 1.1rem;
  right: 1.1rem;
  background: var(--input-bg);
  border: 2px solid var(--border);
  border-radius: 50px;
  padding: 0.35rem 0.75rem;
  cursor: pointer;
  font-size: 1.1rem;
  line-height: 1;
  transition: background var(--transition), border-color var(--transition), transform 0.15s;
}

.dark-toggle:hover {
  transform: scale(1.1);
  border-color: var(--btn-primary);
}

/* Change name button */
.change-name-btn {
  margin-top: 0.75rem;
  font-size: 0.8rem;
  color: var(--text-muted);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.3rem 0.8rem;
}

.change-name-btn:hover {
  color: var(--btn-primary);
  border-color: var(--btn-primary);
}

/* ── Timer Card ── */
.card-timer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
}

.card-timer .card-title {
  align-self: flex-start;
}

.timer-display {
  font-size: clamp(2.8rem, 7vw, 4rem);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--timer-color);
  letter-spacing: 0.06em;
  margin: 0.5rem 0 1.25rem;
  transition: color var(--transition);
}

.timer-controls {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
  justify-content: center;
}

/* ── Tasks Card ── */
.task-input-row {
  display: flex;
  gap: 0.6rem;
  margin-bottom: 0.5rem;
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  max-height: 280px;
  overflow-y: auto;
  margin-top: 0.75rem;
  padding-right: 4px;
}

/* Scrollbar styling */
.task-list::-webkit-scrollbar { width: 5px; }
.task-list::-webkit-scrollbar-track { background: transparent; }
.task-list::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 4px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--input-bg);
  transition: background var(--transition);
}

.task-item input[type="checkbox"] {
  accent-color: var(--btn-primary);
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  cursor: pointer;
}

.task-item .task-text {
  flex: 1;
  font-size: 0.92rem;
  color: var(--text-primary);
  word-break: break-word;
  transition: color var(--transition);
}

.task-item.done .task-text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.task-item .btn-delete {
  background: var(--delete-bg);
  color: #fff;
  border: none;
  border-radius: 7px;
  padding: 0.25rem 0.6rem;
  font-size: 0.78rem;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.2s;
}

.task-item .btn-delete:hover {
  background: var(--delete-h);
}

/* Duplicate warning */
.duplicate-msg {
  font-size: 0.82rem;
  color: var(--duplicate-color);
  min-height: 1.1rem;
  transition: opacity 0.2s;
}

.duplicate-msg.hidden {
  opacity: 0;
  pointer-events: none;
}

/* ── Quick Links Card ── */
.card-links {
  /* full-width — sits in the column flex */
}

.link-input-group {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-bottom: 0.5rem;
}

.link-input-group .text-input {
  flex: 1 1 120px;
}

.link-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.75rem;
}

/* Pill shortcut buttons */
.link-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  background: var(--pill-bg);
  color: var(--pill-text);
  border: none;
  border-radius: 50px;
  padding: 0.4rem 0.9rem;
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s, transform 0.15s;
}

.link-pill:hover {
  background: var(--pill-h);
  transform: translateY(-1px);
}

.link-pill .pill-x {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  background: rgba(255,255,255,0.3);
  border-radius: 50%;
  font-size: 0.7rem;
  line-height: 1;
  transition: background 0.15s;
}

.link-pill .pill-x:hover {
  background: rgba(255,255,255,0.6);
}

/* ══════════════════════════════════
   SHARED INPUTS
══════════════════════════════════ */
.text-input {
  flex: 1;
  padding: 0.65rem 0.9rem;
  border: 2px solid var(--border);
  border-radius: 10px;
  font-size: 0.92rem;
  background: var(--input-bg);
  color: var(--text-primary);
  outline: none;
  transition: border-color var(--transition), background var(--transition);
  min-width: 0;
}

.text-input:focus {
  border-color: var(--btn-primary);
}

.text-input::placeholder {
  color: var(--text-muted);
}

/* ══════════════════════════════════
   BUTTONS
══════════════════════════════════ */
.btn {
  padding: 0.65rem 1.25rem;
  border: none;
  border-radius: 10px;
  font-size: 0.92rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.12s, box-shadow 0.2s;
  white-space: nowrap;
}

.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--btn-primary);
  color: #fff;
}
.btn-primary:hover { background: var(--btn-primary-h); box-shadow: 0 3px 12px rgba(110,87,229,0.35); }

.btn-secondary {
  background: var(--btn-secondary);
  color: #fff;
}
.btn-secondary:hover { filter: brightness(1.1); }

.btn-ghost {
  background: var(--btn-ghost-bg);
  color: var(--text-muted);
  border: 2px solid var(--btn-ghost-border);
}
.btn-ghost:hover { border-color: var(--btn-primary); color: var(--btn-primary); }

/* ══════════════════════════════════
   RESPONSIVE
══════════════════════════════════ */
@media (max-width: 640px) {
  .dashboard {
    padding: 1.25rem 0.9rem 2.5rem;
    gap: 1rem;
  }

  .middle-row {
    grid-template-columns: 1fr;
  }

  .card {
    padding: 1.4rem 1.25rem;
  }

  .timer-controls {
    gap: 0.5rem;
  }

  .link-input-group {
    flex-direction: column;
  }

  .link-input-group .btn {
    width: 100%;
  }

  .task-input-row .btn {
    padding: 0.65rem 0.8rem;
  }

  .dark-toggle {
    top: 0.75rem;
    right: 0.75rem;
  }
}

@media (max-width: 400px) {
  .clock { font-size: 2.4rem; }
  .timer-display { font-size: 2.4rem; }
}

