/* ═══════════════════════════════════════════════
   Life Dashboard — app.js
   ═══════════════════════════════════════════════ */

'use strict';

/* ──────────────────────────────────
   Utility: localStorage helpers
────────────────────────────────── */
const store = {
  get: (key, fallback = null) => {
    try {
      const val = localStorage.getItem(key);
      return val !== null ? JSON.parse(val) : fallback;
    } catch { return fallback; }
  },
  set: (key, value) => {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* quota full */ }
  },
};

/* ──────────────────────────────────
   DOM refs
────────────────────────────────── */
const $  = (id) => document.getElementById(id);
const el = {
  nameModal:      $('name-modal'),
  nameInput:      $('name-input'),
  nameSubmit:     $('name-submit'),
  changeName:     $('change-name'),
  clock:          $('clock'),
  dateDisplay:    $('date-display'),
  greeting:       $('greeting'),
  darkToggle:     $('dark-toggle'),
  toggleIcon:     document.querySelector('.toggle-icon'),
  timerDisplay:   $('timer-display'),
  timerStart:     $('timer-start'),
  timerStop:      $('timer-stop'),
  timerReset:     $('timer-reset'),
  taskInput:      $('task-input'),
  taskAdd:        $('task-add'),
  taskList:       $('task-list'),
  taskDupMsg:     $('task-duplicate-msg'),
  linkNameInput:  $('link-name-input'),
  linkUrlInput:   $('link-url-input'),
  linkAdd:        $('link-add'),
  linkList:       $('link-list'),
  linkErrorMsg:   $('link-error-msg'),
};

/* ══════════════════════════════════
   1. NAME MODAL
══════════════════════════════════ */
const NAME_KEY = 'dashboard_user_name';

function getGreetingWord() {
  const h = new Date().getHours();
  if (h < 12) return 'Good Morning';
  if (h < 17) return 'Good Afternoon';
  if (h < 21) return 'Good Evening';
  return 'Good Night';
}

function updateGreeting() {
  const name = store.get(NAME_KEY, '');
  el.greeting.textContent = name
    ? `${getGreetingWord()}, ${name}! 👋`
    : `${getGreetingWord()}! 👋`;
}

function showModal() {
  el.nameInput.value = store.get(NAME_KEY, '');
  el.nameModal.classList.remove('hidden');
  el.nameInput.focus();
}

function hideModal() {
  el.nameModal.classList.add('hidden');
}

function saveName() {
  const name = el.nameInput.value.trim();
  if (name) {
    store.set(NAME_KEY, name);
    updateGreeting();
    hideModal();
  } else {
    el.nameInput.classList.add('shake');
    el.nameInput.focus();
    setTimeout(() => el.nameInput.classList.remove('shake'), 400);
  }
}

// First-visit check
if (!store.get(NAME_KEY)) {
  showModal();
} else {
  updateGreeting();
}

el.nameSubmit.addEventListener('click', saveName);
el.nameInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') saveName(); });
el.changeName.addEventListener('click', showModal);

// Close modal on backdrop click
el.nameModal.addEventListener('click', (e) => {
  if (e.target === el.nameModal) hideModal();
});

/* ══════════════════════════════════
   2. CLOCK & DATE
══════════════════════════════════ */
const DAYS   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONTHS = ['January','February','March','April','May','June',
                'July','August','September','October','November','December'];

function pad(n) { return String(n).padStart(2, '0'); }

function tickClock() {
  const now = new Date();

  // Clock
  el.clock.textContent = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

  // Date — e.g. "Wednesday, October 7, 2026"
  el.dateDisplay.textContent =
    `${DAYS[now.getDay()]}, ${MONTHS[now.getMonth()]} ${now.getDate()}, ${now.getFullYear()}`;

  // Refresh greeting word on hour boundary (morning → afternoon etc.)
  updateGreeting();
}

tickClock();
setInterval(tickClock, 1000);

/* ══════════════════════════════════
   3. DARK MODE TOGGLE
══════════════════════════════════ */
const DARK_KEY = 'dashboard_dark_mode';

function applyDark(dark) {
  document.body.classList.toggle('dark', dark);
  el.toggleIcon.textContent = dark ? '☀️' : '🌙';
  store.set(DARK_KEY, dark);
}

// Restore on load
applyDark(store.get(DARK_KEY, false));

el.darkToggle.addEventListener('click', () => {
  applyDark(!document.body.classList.contains('dark'));
});

/* ══════════════════════════════════
   4. FOCUS TIMER (Pomodoro 25:00)
══════════════════════════════════ */
const TIMER_TOTAL = 25 * 60; // seconds
let timerSeconds   = TIMER_TOTAL;
let timerInterval  = null;
let timerRunning   = false;

function formatTimer(secs) {
  return `${pad(Math.floor(secs / 60))}:${pad(secs % 60)}`;
}

function renderTimer() {
  el.timerDisplay.textContent = formatTimer(timerSeconds);
}

function timerTick() {
  if (timerSeconds <= 0) {
    clearInterval(timerInterval);
    timerInterval  = null;
    timerRunning   = false;
    el.timerDisplay.textContent = '00:00';
    // Notify user
    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification('Pomodoro complete! 🎉', { body: 'Time for a short break.' });
    } else {
      alert('⏰ Focus session complete! Time for a break.');
    }
    return;
  }
  timerSeconds--;
  renderTimer();
}

el.timerStart.addEventListener('click', () => {
  if (timerRunning) return;
  if (timerSeconds <= 0) timerSeconds = TIMER_TOTAL;
  timerRunning  = true;
  timerInterval = setInterval(timerTick, 1000);
  // Request notification permission
  if ('Notification' in window && Notification.permission === 'default') {
    Notification.requestPermission();
  }
});

el.timerStop.addEventListener('click', () => {
  if (!timerRunning) return;
  clearInterval(timerInterval);
  timerInterval = null;
  timerRunning  = false;
});

el.timerReset.addEventListener('click', () => {
  clearInterval(timerInterval);
  timerInterval = null;
  timerRunning  = false;
  timerSeconds  = TIMER_TOTAL;
  renderTimer();
});

renderTimer();

/* ══════════════════════════════════
   5. TASKS
══════════════════════════════════ */
const TASKS_KEY = 'dashboard_tasks';

// Task shape: { id, text, done }
let tasks = store.get(TASKS_KEY, []);

function saveTasks() {
  store.set(TASKS_KEY, tasks);
}

function buildTaskItem(task) {
  const li = document.createElement('li');
  li.className = 'task-item' + (task.done ? ' done' : '');
  li.dataset.id = task.id;

  const cb = document.createElement('input');
  cb.type    = 'checkbox';
  cb.checked = task.done;
  cb.setAttribute('aria-label', `Mark "${task.text}" as ${task.done ? 'incomplete' : 'complete'}`);
  cb.addEventListener('change', () => toggleTask(task.id));

  const span = document.createElement('span');
  span.className   = 'task-text';
  span.textContent = task.text;

  const del = document.createElement('button');
  del.className   = 'btn-delete';
  del.textContent = 'Delete';
  del.setAttribute('aria-label', `Delete task: ${task.text}`);
  del.addEventListener('click', () => deleteTask(task.id));

  li.append(cb, span, del);
  return li;
}

function renderTasks() {
  el.taskList.innerHTML = '';
  tasks.forEach((t) => el.taskList.appendChild(buildTaskItem(t)));
}

function addTask() {
  const text = el.taskInput.value.trim();
  if (!text) return;

  // Duplicate check (case-insensitive)
  const isDuplicate = tasks.some(
    (t) => t.text.toLowerCase() === text.toLowerCase()
  );

  if (isDuplicate) {
    el.taskDupMsg.classList.remove('hidden');
    el.taskInput.focus();
    clearTimeout(el.taskDupMsg._timer);
    el.taskDupMsg._timer = setTimeout(() => {
      el.taskDupMsg.classList.add('hidden');
    }, 3000);
    return;
  }

  el.taskDupMsg.classList.add('hidden');

  tasks.push({ id: Date.now(), text, done: false });
  saveTasks();
  renderTasks();
  el.taskInput.value = '';
  el.taskInput.focus();
}

function toggleTask(id) {
  tasks = tasks.map((t) =>
    t.id === id ? { ...t, done: !t.done } : t
  );
  saveTasks();
  renderTasks();
}

function deleteTask(id) {
  tasks = tasks.filter((t) => t.id !== id);
  saveTasks();
  renderTasks();
}

el.taskAdd.addEventListener('click', addTask);
el.taskInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') addTask(); });

renderTasks();

/* ══════════════════════════════════
   6. QUICK LINKS
══════════════════════════════════ */
const LINKS_KEY = 'dashboard_links';

// Link shape: { id, name, url }
let links = store.get(LINKS_KEY, [
  { id: 1, name: 'Google',   url: 'https://google.com' },
  { id: 2, name: 'Gmail',    url: 'https://mail.google.com' },
  { id: 3, name: 'Calendar', url: 'https://calendar.google.com' },
]);

function saveLinks() {
  store.set(LINKS_KEY, links);
}

function buildPill(link) {
  const pill = document.createElement('a');
  pill.className = 'link-pill';
  pill.href      = link.url;
  pill.target    = '_blank';
  pill.rel       = 'noopener noreferrer';
  pill.setAttribute('aria-label', `Open ${link.name}`);

  const nameSpan = document.createElement('span');
  nameSpan.textContent = link.name;

  const x = document.createElement('span');
  x.className   = 'pill-x';
  x.textContent = '✕';
  x.setAttribute('role', 'button');
  x.setAttribute('aria-label', `Remove ${link.name}`);
  x.addEventListener('click', (e) => {
    e.preventDefault(); // don't follow link
    e.stopPropagation();
    deleteLink(link.id);
  });

  pill.append(nameSpan, x);
  return pill;
}

function renderLinks() {
  el.linkList.innerHTML = '';
  links.forEach((l) => el.linkList.appendChild(buildPill(l)));
}

function showLinkError(msg) {
  el.linkErrorMsg.textContent = msg;
  el.linkErrorMsg.classList.remove('hidden');
  clearTimeout(el.linkErrorMsg._timer);
  el.linkErrorMsg._timer = setTimeout(() => {
    el.linkErrorMsg.classList.add('hidden');
  }, 3000);
}

function addLink() {
  const name = el.linkNameInput.value.trim();
  const url  = el.linkUrlInput.value.trim();

  if (!name || !url) {
    showLinkError('⚠️ Please enter both a name and a URL.');
    return;
  }

  // Basic URL validation
  let parsedUrl;
  try {
    parsedUrl = new URL(url);
    if (!['http:', 'https:'].includes(parsedUrl.protocol)) throw new Error();
  } catch {
    showLinkError('⚠️ Enter a valid URL (starting with http:// or https://).');
    return;
  }

  el.linkErrorMsg.classList.add('hidden');

  links.push({ id: Date.now(), name, url: parsedUrl.href });
  saveLinks();
  renderLinks();
  el.linkNameInput.value = '';
  el.linkUrlInput.value  = '';
  el.linkNameInput.focus();
}

function deleteLink(id) {
  links = links.filter((l) => l.id !== id);
  saveLinks();
  renderLinks();
}

el.linkAdd.addEventListener('click', addLink);
el.linkUrlInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') addLink(); });

renderLinks();

