// Link shape: { id, name, url }
let links = store.get(LINKS_KEY, [
  { id: 1, name: 'Google',   url: 'https://google.com' },
  { id: 2, name: 'Gmail',    url: 'https://mail.google.com' },
  { id: 3, name: 'Calendar', url: 'https://calendar.google.com' },
]);

function saveLinks() {
  store.set(LINKS_KEY, links);
}

function buildPill(link) {
  const pill = document.createElement('a');
  pill.className = 'link-pill';
  pill.href      = link.url;
  pill.target    = '_blank';
  pill.rel       = 'noopener noreferrer';
  pill.setAttribute('aria-label', `Open ${link.name}`);

  const nameSpan = document.createElement('span');
  nameSpan.textContent = link.name;

  const x = document.createElement('span');
  x.className   = 'pill-x';
  x.textContent = '✕';
  x.setAttribute('role', 'button');
  x.setAttribute('aria-label', `Remove ${link.name}`);
  x.addEventListener('click', (e) => {
    e.preventDefault(); // don't follow link
    e.stopPropagation();
    deleteLink(link.id);
  });

  pill.append(nameSpan, x);
  return pill;
}

function renderLinks() {
  el.linkList.innerHTML = '';
  links.forEach((l) => el.linkList.appendChild(buildPill(l)));
}

function showLinkError(msg) {
  el.linkErrorMsg.textContent = msg;
  el.linkErrorMsg.classList.remove('hidden');
  clearTimeout(el.linkErrorMsg._timer);
  el.linkErrorMsg._timer = setTimeout(() => {
    el.linkErrorMsg.classList.add('hidden');
  }, 3000);
}

function addLink() {
  const name = el.linkNameInput.value.trim();
  const url  = el.linkUrlInput.value.trim();

  if (!name || !url) {
    showLinkError('⚠️ Please enter both a name and a URL.');
    return;
  }

  // Basic URL validation
  let parsedUrl;
  try {
    parsedUrl = new URL(url);
    if (!['http:', 'https:'].includes(parsedUrl.protocol)) throw new Error();
  } catch {
    showLinkError('⚠️ Enter a valid URL (starting with http:// or https://).');
    return;
  }

  el.linkErrorMsg.classList.add('hidden');

  links.push({ id: Date.now(), name, url: parsedUrl.href });
  saveLinks();
  renderLinks();
  el.linkNameInput.value = '';
  el.linkUrlInput.value  = '';
  el.linkNameInput.focus();
}

function deleteLink(id) {
  links = links.filter((l) => l.id !== id);
  saveLinks();
  renderLinks();
}

el.linkAdd.addEventListener('click', addLink);
el.linkUrlInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') addLink(); });

renderLinks();
